    background-color: var(--bg-color);
    margin: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    padding: 1rem;
}

main {
    width: 100%;
    max-width: 450px;
}

.card {
    background-color: var(--card-bg);
    padding: 2.5rem;
    border-radius: 12px;
