    width: 1.25rem;
    height: 1.25rem;
    margin-top: 0.2rem;
    cursor: pointer;
    accent-color: var(--primary-color);
}

input[type="checkbox"]:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}

label {
    cursor: pointer;
    font-weight: 500;
    font-size: 0.95rem;
}

label a {
    color: var(--primary-color);
    text-decoration: underline;
}

label a:hover {
    text-decoration: none;
}

.required-marker {
    color: var(--error-color);
    margin-left: 2px;
}

.helper-text {
    font-size: 0.875rem;
    color: var(--text-secondary);
    margin-top: 0.5rem;
    margin-left: 2rem;
}

.error-text {
    font-size: 0.875rem;
    color: var(--error-color);
    margin-top: 0.5rem;
    margin-left: 2rem;
    font-weight: 600;
}

.submit-button {
    width: 100%;
    background-color: var(--primary-color);
    color: white;
    border: none;
    padding: 0.75rem 1rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 6px;
    cursor: pointer;
    transition: background-color 0.2s;
}

.submit-button:hover {
    background-color: var(--primary-hover);
}

.submit-button:focus-visible {
    outline: none;
    box-shadow: var(--focus-ring);
}

@media (max-width: 480px) {
    .card {
        padding: 1.5rem;
    }
}
