document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('consent-form');
    const checkbox = document.getElementById('terms-consent');
    const errorText = document.getElementById('terms-error');

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
            // Show error message
            errorText.hidden = false;
            checkbox.setAttribute('aria-invalid', 'true');

            // Focus the checkbox per accessibility principles
            checkbox.focus();
        } else {
            // Success - clear error and proceed
            errorText.hidden = true;
            checkbox.setAttribute('aria-invalid', 'false');

            // Simulate form submission
            alert('Form submitted successfully! Thank you for agreeing to our terms.');
            // form.submit(); // Uncomment for actual submission
        }
    });

    // Clear error as soon as user checks the box
    checkbox.addEventListener('change', () => {
        if (checkbox.checked) {
            errorText.hidden = true;
            checkbox.setAttribute('aria-invalid', 'false');
        }
    });
});

