    <main>
        <div class="card">
            <h1>Review our terms</h1>
            <p class="intro-text">Before you continue, please take a moment to review and agree to our terms of use.</p>

            <form id="consent-form" novalidate>
                <div class="form-field">
                    <div class="checkbox-container">
                        <input type="checkbox" id="terms-consent" name="terms" required aria-describedby="terms-help">
                        <label for="terms-consent">
                            I agree to the <a href="#" target="_blank">Terms of Use <span class="sr-only">(opens in a new window)</span></a> and <a href="#" target="_blank">Privacy Policy <span class="sr-only">(opens in a new window)</span></a> <span class="required-marker" aria-hidden="true">*</span>
                        </label>
                    </div>
                    <p id="terms-help" class="helper-text">Accepting these terms is required for account creation.</p>
                    <p id="terms-error" class="error-text" hidden aria-live="polite">Error: You must agree to the terms to proceed.</p>
                </div>

                <button type="submit" class="submit-button">Agree and continue</button>
            </form>
        </div>
    </main>
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('consent-form');
            const checkbox = document.getElementById('terms-consent');
            const errorText = document.getElementById('terms-error');

            form.addEventListener('submit', (event) => {
                event.preventDefault();

                if (!checkbox.checked) {
                    // Show error message
                    errorText.hidden = false;
                    checkbox.setAttribute('aria-invalid', 'true');
                    checkbox.setAttribute('aria-describedby', 'terms-help terms-error');

                    // Focus the checkbox per accessibility principles
                    checkbox.focus();
                } else {
                    // Success - clear error and proceed
                    errorText.hidden = true;
                    checkbox.setAttribute('aria-invalid', 'false');
                    checkbox.setAttribute('aria-describedby', 'terms-help');

                    // Simulate form submission
                    alert('Form submitted successfully! Thank you for agreeing to our terms.');
                    // form.submit(); // Uncomment for actual submission
                }
            });

            // Clear error as soon as user checks the box
            checkbox.addEventListener('change', () => {
                if (checkbox.checked) {
                    errorText.hidden = true;
                    checkbox.setAttribute('aria-invalid', 'false');
                    checkbox.setAttribute('aria-describedby', 'terms-help');
                }
            });
        });
    </script>
</body>
</html>
